#!/usr/bin/env node
/**
 * generate-client-index.js — Generate a lightweight client-side tool index.
 *
 * Reads tools-chunk-0..5.ts + proSlugs from tools-constants.ts and emits
 * src/registry/tools-client-index.ts with only the fields client components need:
 *   { id, name, slug, category, description, isPro }
 *
 * Run: node scripts/generate-client-index.js
 * Guard: this file is auto-generated — DO NOT EDIT BY HAND.
 */
const fs = require('fs');
const path = require('path');

const REGISTRY_DIR = path.join(__dirname, '..', 'src', 'registry');
const OUT_FILE = path.join(REGISTRY_DIR, 'tools-client-index.ts');

// --- 1. Parse proSlugs from tools-constants.ts ---
const constantsSrc = fs.readFileSync(path.join(REGISTRY_DIR, 'tools-constants.ts'), 'utf8');
const proMatch = constantsSrc.match(/export const proSlugs: string\[\] = \[([\s\S]*?)\];/);
const proSlugs = new Set(
  proMatch
    ? proMatch[1].match(/"([^"]+)"/g)?.map(s => s.replace(/"/g, '')) ?? []
    : []
);

// --- 2. Parse tool entries from chunk files ---
const entries = [];
for (let i = 0; i <= 5; i++) {
  const chunkPath = path.join(REGISTRY_DIR, `tools-chunk-${i}.ts`);
  const src = fs.readFileSync(chunkPath, 'utf8');

  // Match each tool object: split on { followed by newline + any field (id, name, slug, etc.)
  const blocks = src.split(/\{(?=\s*\n\s*(?:id|name|slug):)/);
  for (const block of blocks) {
    // Must contain both id and slug to be a valid tool entry
    if (!block.includes('id:') || !block.includes('slug:')) continue;

    const get = (field) => {
      // Match: field: "value" or field: 'value'
      const re = new RegExp(field + ':\\s*[\'"`]([^\'"`]*)[\'"`]');
      const m = block.match(re);
      return m ? m[1] : '';
    };

    const id = get('id');
    const name = get('name');
    const slug = get('slug');
    const category = get('category');
    const description = get('description');
    // showInCategory: only include if explicitly set to false (default is true/undefined)
    const showInCategoryRaw = get('showInCategory');
    const showInCategory = showInCategoryRaw === 'false' ? false : undefined;

    if (id && slug) {
      const entry = { id, name, slug, category, description, isPro: proSlugs.has(slug) };
      if (showInCategory === false) entry.showInCategory = false;
      entries.push(entry);
    }
  }
}

// --- 3. Also check entries that have isPro directly in the chunk ---
for (let i = 0; i <= 5; i++) {
  const chunkPath = path.join(REGISTRY_DIR, `tools-chunk-${i}.ts`);
  const src = fs.readFileSync(chunkPath, 'utf8');
  // Find slugs that have isPro: true in the chunk itself
  const isProBlocks = src.split(/\{(?=\s*\n\s*id:)/);
  for (const block of isProBlocks) {
    if (!block.includes('isPro: true')) continue;
    const slugMatch = block.match(/slug:\s*[\'"`]([^\'"`]*)[\'"`]/);
    if (slugMatch) {
      const entry = entries.find(e => e.slug === slugMatch[1]);
      if (entry) entry.isPro = true;
    }
  }
}

// --- 4. Generate output ---
const output = `// Auto-generated by \`node scripts/generate-client-index.js\` — DO NOT EDIT BY HAND.
// Regenerate: node scripts/generate-client-index.js
// Source: tools-chunk-0..5.ts + proSlugs from tools-constants.ts

export interface ClientToolEntry {
  id: string;
  name: string;
  slug: string;
  category: string;
  description: string;
  isPro: boolean;
  showInCategory?: boolean;
}

export const clientToolsRegistry: ClientToolEntry[] = ${JSON.stringify(entries, null, 2)};

const _clientToolsBySlug = new Map(clientToolsRegistry.map(t => [t.slug, t]));
export function getClientToolBySlug(slug: string): ClientToolEntry | undefined {
  return _clientToolsBySlug.get(slug);
}
`;

fs.writeFileSync(OUT_FILE, output);
console.log(`✓ Generated tools-client-index.ts (${entries.length} tools, ${(Buffer.byteLength(output) / 1024).toFixed(1)}KB)`);
